export function mapNormalizedGridToWebGL(json, snappedBounds, hourOffset, layer = 'waves', model = 'GFS') {
  if (!json || !json.grid || !Array.isArray(json.grid.vectors)) {
    throw new Error("Invalid normalized grid response structure");
  }

